import{_ as t,o as e,c as r,a2 as a}from"./chunks/framework.A5mep7Fe.js";const L=JSON.parse('{"title":"🖼️ 03 · 多模态与语音生成","description":"","frontmatter":{},"headers":[],"relativePath":"02-算法岗-AIGC生成式/03-多模态与语音生成.md","filePath":"02-算法岗-AIGC生成式/03-多模态与语音生成.md","lastUpdated":1786806808000}'),n={name:"02-算法岗-AIGC生成式/03-多模态与语音生成.md"};function l(i,o,s,c,p,h){return e(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="🖼️-03-·-多模态与语音生成" tabindex="-1">🖼️ 03 · 多模态与语音生成 <a class="header-anchor" href="#🖼️-03-·-多模态与语音生成" aria-label="Permalink to &quot;🖼️ 03 · 多模态与语音生成&quot;">​</a></h1><blockquote><p>「看、听、说」的能力：VLM（视觉语言模型）、文生图/视频、TTS 语音合成。</p></blockquote><hr><h2 id="一、多模态大模型-vlm" tabindex="-1">一、多模态大模型（VLM） <a class="header-anchor" href="#一、多模态大模型-vlm" aria-label="Permalink to &quot;一、多模态大模型（VLM）&quot;">​</a></h2><p><strong>目标</strong>：让 LLM 理解图像/视频，并能图文混合推理。主流架构：</p><ol><li><strong>视觉编码器</strong>（ViT/CLIP Image Encoder）把图像编码为视觉 token</li><li>** projector/Adapter**（如 MLP、Q-Former）把视觉 token 对齐到文本空间</li><li><strong>LLM</strong> 接收「文本 token + 视觉 token」做统一推理</li></ol><p>代表：LLaVA（简洁对齐）、Qwen-VL、GPT-4V、Gemini（原生多模态）。</p><p><strong>训练两阶段</strong>：先对齐（冻 LLM，训 projector）+ 再指令微调（解冻端到端）。</p><hr><h2 id="二、文生图-文生视频" tabindex="-1">二、文生图 / 文生视频 <a class="header-anchor" href="#二、文生图-文生视频" aria-label="Permalink to &quot;二、文生图 / 文生视频&quot;">​</a></h2><ul><li><strong>文生图</strong>：CLIP 文本编码器 → 条件注入 Diffusion（见 <code>01-Diffusion</code>）。代表 Stable Diffusion、DALL·E、Midjourney。</li><li><strong>文生视频</strong>：在时空上扩展 Diffusion（3D U-Net / 时空注意力），或自回归逐帧生成。代表 Sora（扩散 transformer DiT）、Runway、可灵。</li></ul><p><strong>难点</strong>：时序一致性、运动合理性、长视频连贯、算力昂贵。</p><hr><h2 id="三、语音生成-tts-语音大模型" tabindex="-1">三、语音生成（TTS / 语音大模型） <a class="header-anchor" href="#三、语音生成-tts-语音大模型" aria-label="Permalink to &quot;三、语音生成（TTS / 语音大模型）&quot;">​</a></h2><ul><li><strong>传统 TTS</strong>：文本前端 → 声学模型（FastSpeech）→ 声码器（HiFi-GAN）合成波形。</li><li><strong>神经 codec + LLM</strong>：把语音离散化为 token（如 EnCodec），用 LLM 做「语音自回归生成」，实现自然语音/克隆/情感。代表 VALL-E、ChatTTS。</li><li><strong>语音理解</strong>：Whisper（ASR）、语音大模型（GPT-4o 类原生语音）。</li></ul><hr><h2 id="四、跨模态对齐的本质" tabindex="-1">四、跨模态对齐的本质 <a class="header-anchor" href="#四、跨模态对齐的本质" aria-label="Permalink to &quot;四、跨模态对齐的本质&quot;">​</a></h2><blockquote><p>多模态的核心难题是<strong>表征对齐</strong>——让「猫的图像 token」和「&#39;猫&#39;的文本 token」在 LLM 空间里靠近。CLIP 用「图文对比学习」解决了第一步，后续工作都在做「更好的对齐 + 更紧的融合」。</p></blockquote><hr><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：LLaVA 为什么训 projector 而不是直接冻视觉编码器？</strong></p><blockquote><p>视觉特征与文本空间维度/分布不同，需一个可学习的适配器把视觉 token 映射进 LLM 可理解的空间；先冻 LLM 保语言能力的稳定，再微调融合。</p></blockquote><p><strong>Q2：文生视频比文生图难在哪？</strong></p><blockquote><p>多了时间维，要保时序一致与运动合理；显存/算力随帧数线性涨；长视频连贯难。</p></blockquote><p><strong>Q3：VALL-E 类语音 LLM 的 idea 是什么？</strong></p><blockquote><p>用神经 codec 把语音变离散 token，再用 LLM 自回归生成语音 token，最后解码回波形，实现「像生成文字一样生成语音」。</p></blockquote><hr><p>➡️ 返回：<a href="./README">02-算法岗-AIGC生成式 README</a> ｜ 进入：<a href="./../03-算法岗-AI-Agent/README">03-算法岗-AI-Agent</a></p>',28)])])}const u=t(n,[["render",l]]);export{L as __pageData,u as default};
